/**
 * utilgen — a small-scale utility-class CSS generator in the Tailwind spirit.
 *
 * Given a config with a spacing scale (and optionally a screens map), produces
 * margin/padding utilities for all sides, x/y axes and individual edges,
 * display utilities, and per-screen prefixed variants wrapped in media queries
 * (e.g. `.md\:px-4` inside `@media (min-width: 768px)`).
 *
 * Output ordering is fully deterministic.
 */

export interface UtilgenConfig {
  /** Spacing scale, e.g. { '0': '0', '1': '0.25rem', '2': '0.5rem', ... } */
  spacing: Record<string, string>;
  /**
   * Responsive screen breakpoints. Keys become prefixes (`md:px-4`),
   * values are min-width media query values.
   */
  screens?: Record<string, string>;
}

/** Fixed side order for deterministic output: all-axis, x, y, then top→left. */
const SIDE_PREFIXES = ['', 'x-', 'y-', 't-', 'r-', 'b-', 'l-'] as const;

const DISPLAY_UTILITIES: ReadonlyArray<readonly [string, string]> = [
  ['block', 'block'],
  ['inline-block', 'inline-block'],
  ['inline', 'inline'],
  ['flex', 'flex'],
  ['grid', 'grid'],
  ['hidden', 'none'],
];

/** Expand `m`, `mx`, `my`, `mt`, ... into their CSS property names. */
function spacingProperties(prefix: string): string[] {
  switch (prefix) {
    case '':
      return ['margin'];
    case 'x-':
      return ['margin-left', 'margin-right'];
    case 'y-':
      return ['margin-top', 'margin-bottom'];
    case 't-':
      return ['margin-top'];
    case 'r-':
      return ['margin-right'];
    case 'b-':
      return ['margin-bottom'];
    case 'l-':
      return ['margin-left'];
    default:
      throw new Error(`Unknown side prefix: ${prefix}`);
  }
}

/** Escape special characters in a class name for use in a CSS selector. */
export function escapeClassName(name: string): string {
  return name.replace(/([:.#/\\[\]()])/g, '\\$1');
}

interface Rule {
  selector: string;
  declarations: string[];
}

function formatRule(rule: Rule, indent = ''): string {
  const body = rule.declarations.map((d) => `${indent}  ${d};`).join('\n');
  return `${indent}.${rule.selector} {\n${body}\n${indent}}`;
}

function spacingRules(
  kind: 'm' | 'p',
  scaleKeys: string[],
  spacing: Record<string, string>,
): Rule[] {
  const propertyBase = kind === 'm' ? 'margin' : 'padding';
  const rules: Rule[] = [];
  for (const prefix of SIDE_PREFIXES) {
    for (const key of scaleKeys) {
      const properties =
        prefix === ''
          ? [propertyBase]
          : spacingProperties(kind + '-' + prefix).map((p) => p);
      rules.push({
        selector: escapeClassName(`${kind}-${prefix}${key}`),
        declarations: properties.map((p) => `${p}: ${spacing[key]}`),
      });
    }
  }
  return rules;
}

function displayRules(): Rule[] {
  return DISPLAY_UTILITIES.map(([name, value]) => ({
    selector: escapeClassName(name),
    declarations: [`display: ${value}`],
  }));
}

/**
 * Generate the full utility stylesheet as a CSS string.
 * Ordering: base utilities first, then one media-query block per screen
 * (in screen insertion order), each containing prefixed variants of every
 * utility in the same deterministic order as the base layer.
 */
export function generate(config: UtilgenConfig): string {
  const scaleKeys = Object.keys(config.spacing);
  if (scaleKeys.length === 0) {
    throw new Error('config.spacing must define at least one key');
  }

  const chunks: string[] = [];

  // Base layer: margins, paddings, display utilities.
  const baseRules = [
    ...spacingRules('m', scaleKeys, config.spacing),
    ...spacingRules('p', scaleKeys, config.spacing),
    ...displayRules(),
  ];
  chunks.push(baseRules.map((r) => formatRule(r)).join('\n'));

  // Screen-prefixed variants, wrapped in min-width media queries.
  if (config.screens) {
    for (const [screen, minWidth] of Object.keys(config.screens).map(
      (k) => [k, config.screens![k]] as const,
    )) {
      const variantRules = baseRules.map((rule) => ({
        selector: escapeClassName(`${screen}:${unescapeSelector(rule.selector)}`),
        declarations: rule.declarations,
      }));
      chunks.push(
        `@media (min-width: ${minWidth}) {\n${variantRules
          .map((r) => formatRule(r, '  '))
          .join('\n')}\n}`,
      );
    }
  }

  return chunks.join('\n\n') + '\n';
}

/** Inverse of the escaping applied inside spacing/display rule generation. */
function unescapeSelector(selector: string): string {
  return selector.replace(/\\(.)/g, '$1');
}

