import { describe, it, expect } from 'vitest';
import postcss from 'postcss';
import { generate, type UtilgenConfig } from '../src/index';

export const fixedConfig: UtilgenConfig = {
  spacing: {
    '0': '0',
    '1': '0.25rem',
    '2': '0.5rem',
    '4': '1rem',
    '8': '2rem',
  },
  screens: {
    sm: '640px',
    md: '768px',
    lg: '1024px',
  },
};

const DISPLAY_COUNT = 6; // block, inline-block, inline, flex, grid, hidden
const SIDES_PER_KIND = 7; // (all), x, y, t, r, b, l
const SCALE_KEYS = Object.keys(fixedConfig.spacing).length;

/** Parse CSS and return all top-level rules with their enclosing at-rule. */
function parseRules(css: string) {
  const root = postcss.parse(css);
  const rules: { selector: string; media: string | null }[] = [];
  root.walkRules((rule) => {
    const parent = rule.parent;
    const media =
      parent && parent.type === 'atrule' && (parent as postcss.AtRule).name === 'media'
        ? ((parent as postcss.AtRule).params ?? null)
        : null;
    rules.push({ selector: rule.selector, media });
  });
  return rules;
}

describe('generate', () => {
  const css = generate(fixedConfig);

  it('matches the snapshot', () => {
    expect(css).toMatchSnapshot();
  });

  it('produces exactly base + one copy per screen of every utility', () => {
    const screens = Object.keys(fixedConfig.screens!);
    const expectedPerScreen =
      SIDES_PER_KIND * SCALE_KEYS * 2 /* m + p */ + DISPLAY_COUNT;
    const expectedTotal = expectedPerScreen * (1 + screens.length);

    const rules = parseRules(css);
    expect(rules.length).toBe(expectedTotal);

    // Base layer count.
    const baseCount = rules.filter((r) => r.media === null).length;
    expect(baseCount).toBe(expectedPerScreen);

    // Each screen contributes exactly its share, all inside a media query.
    for (const screen of screens) {
      const minWidth = fixedConfig.screens![screen];
      const inQuery = rules.filter(
        (r) => r.media === `(min-width: ${minWidth})`,
      );
      expect(inQuery.length).toBe(expectedPerScreen);
      expect(
        inQuery.every((r) => r.selector.startsWith(`.${screen}\\:`)),
      ).toBe(true);
    }
  });

  it('sides × scale math holds exactly for margins and paddings', () => {
    const rules = parseRules(css);
    const sidePrefixes = ['', 'x-', 'y-', 't-', 'r-', 'b-', 'l-'];

    for (const kind of ['m', 'p']) {
      for (const prefix of sidePrefixes) {
        for (const key of Object.keys(fixedConfig.spacing)) {
          const selector = `.${kind}-${prefix}${key}`;
          const matches = rules.filter((r) => r.selector === selector);
          // Appears once in base + once per screen variant.
          expect(matches.length).toBe(1 + Object.keys(fixedConfig.screens!).length);

          const value = fixedConfig.spacing[key];
          const decls = postcss
            .parse(css)
            .walkRules(selector)
            ? collectDecls(css, selector)
            : [];
          expect(decls.length).toBeGreaterThan(0);
          for (const decl of decls) {
            expect(decl.value).toBe(value);
          }

          // Property coverage per side shape.
          if (prefix === '') {
            expect(decls.map((d) => d.prop)).toEqual([`${kind === 'm' ? 'margin' : 'padding'}`]);
          } else if (prefix === 'x-') {
            expect(new Set(decls.map((d) => d.prop))).toEqual(
              new Set([`margin-left`, `margin-right`]),
            );
          } else if (prefix === 'y-') {
            expect(new Set(decls.map((d) => d.prop))).toEqual(
              new Set([`margin-top`, `margin-bottom`]),
            );
          }
        }
      }
    }
  });

  it('wraps md variants inside the correct media query', () => {
    const rules = parseRules(css);
    const mdPx4 = rules.find((r) => r.selector === '.md\\:px-4');
    expect(mdPx4).toBeDefined();
    expect(mdPx4!.media).toBe('(min-width: 768px)');
    // And it must NOT appear in the base layer or other screens' queries.
    const stray = rules.filter(
      (r) =>
        r.selector === '.md\\:px-4' &&
        r.media !== '(min-width: 768px)',
    );
    expect(stray).toHaveLength(0);
  });

  it('escapes colons in prefixed selectors', () => {
    expect(css).toContain('.md\\:mt-2');
    expect(css).toContain('@media (min-width: 1024px)');
  });
});

function collectDecls(
  css: string,
  selector: string,
): { prop: string; value: string }[] {
  const out: { prop: string; value: string }[] = [];
  postcss.parse(css).walkRules(selector, (rule) => {
    rule.walkDecls((decl) => {
      out.push({ prop: decl.prop, value: decl.value });
    });
  });
  return out;
}

