/**
 * utilgen — a small-scale utility-class CSS generator in the Tailwind spirit.
 *
 * Given a config with a spacing scale (and optionally a screens map), produces
 * margin/padding utilities for all sides, x/y axes and individual edges
 * (m-4, mt-2, px-8, ...), display utilities, and per-screen prefixed variants
 * wrapped in min-width media queries (e.g. `.md\:px-4` inside
 * `@media (min-width: 768px)`).
 *
 * Output ordering is fully deterministic.
 */

export interface UtilgenConfig {
  /** Spacing scale, e.g. { '0': '0', '1': '0.25rem', ... } */
  spacing: Record<string, string>;
  /**
   * Responsive screen breakpoints. Keys become prefixes (`md:px-4`),
   * values are the min-width media query lengths.
   */
  screens?: Record<string, string>;
}

interface SpacingGroup {
  /** Utility class fragment, e.g. '' (m-1), 'x' (px-1), 't' (mt-1). */
  suffix: string;
  /** CSS properties the utility sets. */
  properties: string[];
}

const MARGIN_GROUPS: SpacingGroup[] = [
  { suffix: '', properties: ['margin'] },
  { suffix: 'x', properties: ['margin-left', 'margin-right'] },
  { suffix: 'y', properties: ['margin-top', 'margin-bottom'] },
  { suffix: 't', properties: ['margin-top'] },
  { suffix: 'r', properties: ['margin-right'] },
  { suffix: 'b', properties: ['margin-bottom'] },
  { suffix: 'l', properties: ['margin-left'] },
];

const PADDING_GROUPS: SpacingGroup[] = [
  { suffix: '', properties: ['padding'] },
  { suffix: 'x', properties: ['padding-left', 'padding-right'] },
  { suffix: 'y', properties: ['padding-top', 'padding-bottom'] },
  { suffix: 't', properties: ['padding-top'] },
  { suffix: 'r', properties: ['padding-right'] },
  { suffix: 'b', properties: ['padding-bottom'] },
  { suffix: 'l', properties: ['padding-left'] },
];

const DISPLAY_UTILITIES: ReadonlyArray<readonly [string, string]> = [
  ['block', 'block'],
  ['inline-block', 'inline-block'],
  ['inline', 'inline'],
  ['flex', 'flex'],
  ['grid', 'grid'],
  ['hidden', 'none'],
];

/** Escape special characters (notably colons) in a class name for selectors. */
export function escapeClassName(name: string): string {
  return name.replace(/([:.#/\\[\]()])/g, '\\$1');
}

interface Rule {
  /** Fully escaped selector (without leading dot). */
  selector: string;
  declarations: string[];
}

function formatRule(rule: Rule, indent = ''): string {
  const body = rule.declarations.map((d) => `${indent}  ${d};`).join('\n');
  return `${indent}.${rule.selector} {\n${body}\n${indent}}`;
}

function spacingRules(
  kind: 'm' | 'p',
  groups: SpacingGroup[],
  scaleKeys: string[],
  spacing: Record<string, string>,
): Rule[] {
  const rules: Rule[] = [];
  for (const group of groups) {
    const className = kind + (group.suffix ? `-${group.suffix}` : '');
    for (const key of scaleKeys) {
      rules.push({
        selector: escapeClassName(`${className}-${key}`),
        declarations: group.properties.map((p) => `${p}: ${spacing[key]}`),
      });
    }
  }
  return rules;
}

/**
 * Generate the full utility stylesheet as a CSS string.
 *
 * Ordering: base utilities first (margin groups, padding groups, display),
 * then one media-query block per screen in insertion order, each containing
 * prefixed variants of every utility in the same deterministic order.
 */
export function generate(config: UtilgenConfig): string {
  const scaleKeys = Object.keys(config.spacing);
  if (scaleKeys.length === 0) {
    throw new Error('config.spacing must define at least one key');
  }

  const chunks: string[] = [];

  // Base layer.
  const baseRules: Rule[] = [
    ...spacingRules('m', MARGIN_GROUPS, scaleKeys, config.spacing),
    ...spacingRules('p', PADDING_GROUPS, scaleKeys, config.spacing),
    ...DISPLAY_UTILITIES.map(([name, value]) => ({
      selector: escapeClassName(name),
      declarations: [`display: ${value}`],
    })),
  ];
  chunks.push(baseRules.map((r) => formatRule(r)).join('\n'));

  // Screen-prefixed variants inside min-width media queries.
  if (config.screens) {
    for (const screen of Object.keys(config.screens)) {
      const minWidth = config.screens[screen];
      const variantRules = baseRules.map((rule) => ({
        selector: escapeClassName(`${screen}:${rule.selector.replace(/\\(.)/g, '$1')}`),
        declarations: rule.declarations,
      }));
      chunks.push(
        `@media (min-width: ${minWidth}) {\n${variantRules
          .map((r) => formatRule(r, '  '))
          .join('\n')}\n}`,
      );
    }
  }

  return chunks.join('\n\n') + '\n';
}

